package org.brightstats.desktop;
import java.text.*;
import javafx.application.Platform;
import javafx.application.ColorScheme;
import java.util.*;
import javafx.collections.ListChangeListener;
import javafx.scene.*;
import javafx.scene.control.*;
import javafx.stage.Window;
import org.brightstats.data.UserPreferences;

/** Presentation only: numeric results, data labels and saved model identities are never translated. */
final class UiAppearance {
    private UiAppearance(){}
    private static UserPreferences current=UserPreferences.defaults();
    private static final Map<Parent,String> originalStyles=new WeakHashMap<>();
    private static boolean installed,translating;
    private static ColorScheme systemScheme=ColorScheme.LIGHT;
    private static final String KEY="brightstats.uiText";
    static UserPreferences current(){return current;}
    static UserPreferences.Theme theme(){return effectiveTheme(current.theme(),systemScheme);}
    static void install(UserPreferences preferences){UiMotion.stopAll();current=preferences;if(!installed){installed=true;systemScheme=Platform.getPreferences().getColorScheme();Platform.getPreferences().colorSchemeProperty().addListener((o,a,b)->systemSchemeChanged(b));Platform.getPreferences().reducedMotionProperty().addListener((o,a,b)->refreshWindows());Window.getWindows().addListener((ListChangeListener<Window>)change->{while(change.next())for(var window:change.getAddedSubList()){if(window.getScene()!=null)apply(window.getScene());window.sceneProperty().addListener((observable,old,scene)->{if(scene!=null)apply(scene);});}});}for(var window:Window.getWindows())if(window.getScene()!=null)apply(window.getScene());}
    static void systemSchemeChanged(ColorScheme scheme){systemScheme=scheme;refreshWindows();}
    static void refreshWindows(){UiMotion.stopAll();for(var window:Window.getWindows())if(window.getScene()!=null)apply(window.getScene());}
    static UserPreferences.Theme effectiveTheme(UserPreferences.Theme requested,ColorScheme system){return requested==UserPreferences.Theme.SYSTEM?(system==ColorScheme.DARK?UserPreferences.Theme.DARK:UserPreferences.Theme.LIGHT):requested;}
    static UserPreferences.Motion effectiveMotion(){return current.motion()==UserPreferences.Motion.FULL&&Platform.getPreferences().isReducedMotion()?UserPreferences.Motion.REDUCED:current.motion();}
    static void apply(Scene scene){String css=UiAppearance.class.getResource("/appearance.css").toExternalForm();if(!scene.getStylesheets().contains(css))scene.getStylesheets().add(css);Parent root=scene.getRoot();originalStyles.putIfAbsent(root,root.getStyle());root.getStyleClass().removeIf(value->value.startsWith("theme-")||value.startsWith("accent-")||value.startsWith("density-")||value.startsWith("motion-")||value.startsWith("layout-")||value.startsWith("chart-preset-"));root.getStyleClass().add("theme-"+effectiveTheme(current.theme(),systemScheme).name().toLowerCase(Locale.ROOT).replace('_','-'));root.getStyleClass().add("accent-"+current.accent().name().toLowerCase(Locale.ROOT));root.getStyleClass().add("density-"+current.density().name().toLowerCase(Locale.ROOT));root.getStyleClass().add("motion-"+effectiveMotion().name().toLowerCase(Locale.ROOT));root.getStyleClass().add("layout-"+current.layout().name().toLowerCase(Locale.ROOT));root.getStyleClass().add("chart-preset-"+current.chartPreset().name().toLowerCase(Locale.ROOT));root.setStyle(originalStyles.get(root)+";-fx-font-size:"+current.fontSize()+"px;");refresh(root);}
    static void refresh(Node node){if(node.getProperties().get("brightstats.redraw") instanceof Runnable redraw)redraw.run();if(node instanceof ProgressIndicator progress&&Boolean.TRUE.equals(progress.getProperties().get("brightstats.activeActivity")))progress.setVisible(effectiveMotion()==UserPreferences.Motion.FULL);if(node instanceof Button button&&!button.getProperties().containsKey(KEY)&&WORDS.containsKey(button.getText()))mark(button,button.getText());if(node instanceof Labeled labeled&&labeled.getProperties().containsKey(KEY)&&!labeled.textProperty().isBound()){translating=true;try{labeled.setText(text((String)labeled.getProperties().get(KEY)));}finally{translating=false;}}if(node instanceof Parent parent)for(var child:parent.getChildrenUnmodifiable())refresh(child);}
    static Button button(String text){return mark(new Button(text),text);}
    static Label label(String text){return mark(new Label(text),text);}
    static <T extends Labeled>T mark(T control,String text){control.getProperties().put(KEY,text);control.setText(text(text));control.textProperty().addListener((observable,old,value)->{if(!translating)control.getProperties().put(KEY,value);});return control;}
    static String text(String english){var translations=WORDS.get(english);return translations==null||current.language()==UserPreferences.Language.ENGLISH?english:translations[current.language().ordinal()-1];}
    static String number(double value){if(Double.isNaN(value))return "\u2014";if(Double.isInfinite(value))return value>0?"\u221e":"\u2212\u221e";if(current.numberLocale().equals("en-US")&&current.fractionDigits()==6){if(value!=0&&(Math.abs(value)<1e-6||Math.abs(value)>=1e9))return String.format(Locale.ROOT,"%.6e",value);return String.format(Locale.ROOT,"%.6f",value);}String pattern=value!=0&&(Math.abs(value)<1e-6||Math.abs(value)>=1e9)?"0"+(current.fractionDigits()==0?"":"."+"0".repeat(current.fractionDigits()))+"E0":"0"+(current.fractionDigits()==0?"":"."+"0".repeat(current.fractionDigits()));DecimalFormat format=new DecimalFormat(pattern,DecimalFormatSymbols.getInstance(Locale.forLanguageTag(current.numberLocale())));format.setGroupingUsed(false);return format.format(value);}
    static String probability(double value){if(!(value>0&&value<.0001))return number(value);if(current.numberLocale().equals("en-US"))return String.format(Locale.ROOT,"%.4e",value);DecimalFormat format=new DecimalFormat("0.0000E0",DecimalFormatSymbols.getInstance(Locale.forLanguageTag(current.numberLocale())));format.setGroupingUsed(false);return format.format(value);}
    private static final Map<String,String[]> WORDS=Map.ofEntries(
        entry("Workspace...","Espacio de trabajo...","Espace de travail...","Arbeitsbereich..."),entry("Save in workspace","Guardar en espacio de trabajo","Enregistrer dans l'espace","Im Arbeitsbereich speichern"),entry("Named models...","Modelos guardados...","Modèles enregistrés...","Gespeicherte Modelle..."),entry("Open project","Abrir proyecto","Ouvrir un projet","Projekt öffnen"),entry("Import data...","Importar datos...","Importer des données...","Daten importieren..."),entry("Save project as...","Guardar proyecto como...","Enregistrer le projet sous...","Projekt speichern unter..."),entry("Export data workbook...","Exportar datos...","Exporter les données...","Daten exportieren..."),entry("Export graphic...","Exportar gráfico...","Exporter le graphique...","Grafik exportieren..."),entry("Preferences...","Preferencias...","Préférences...","Einstellungen..."),
        entry("MODEL","MODELO","MODÈLE","MODELL"),entry("MODEL EDITORS","EDITORES DE MODELOS","ÉDITEURS DE MODÈLES","MODELLEDITOREN"),entry("CALCULATE","CALCULAR","CALCULER","BERECHNEN"),entry("REPORTS","INFORMES","RAPPORTS","BERICHTE"),entry("Add construct","Añadir constructo","Ajouter un construit","Konstrukt hinzufügen"),entry("Edit selected construct...","Editar constructo...","Modifier le construit...","Konstrukt bearbeiten..."),entry("Connect constructs","Conectar constructos","Relier les construits","Konstrukte verbinden"),entry("Arrange model","Organizar modelo","Organiser le modèle","Modell anordnen"),entry("Remove selected constructs","Eliminar constructos","Supprimer les construits","Konstrukte entfernen"),entry("Undo","Deshacer","Annuler","Rückgängig"),entry("Redo","Rehacer","Rétablir","Wiederholen"),entry("Copy constructs","Copiar constructos","Copier les construits","Konstrukte kopieren"),entry("Paste constructs","Pegar constructos","Coller les construits","Konstrukte einfügen"),
        entry("New empty project","Nuevo proyecto vacío","Nouveau projet vide","Neues leeres Projekt"),entry("Add current project","Añadir proyecto actual","Ajouter le projet actuel","Aktuelles Projekt hinzufügen"),entry("Save current","Guardar actual","Enregistrer l'actuel","Aktuelles speichern"),entry("Open selected","Abrir seleccionado","Ouvrir la sélection","Auswahl öffnen"),entry("Rename","Renombrar","Renommer","Umbenennen"),entry("Duplicate saved project","Duplicar proyecto guardado","Dupliquer le projet enregistré","Gespeichertes Projekt duplizieren"),entry("Remove from list","Quitar de la lista","Retirer de la liste","Aus Liste entfernen"),entry("Save new snapshot","Guardar nueva copia","Enregistrer une copie","Neue Modellkopie speichern"),entry("Activate snapshot","Activar copia","Activer la copie","Modellkopie aktivieren"),entry("Duplicate","Duplicar","Dupliquer","Duplizieren"),entry("Remove snapshot","Eliminar copia","Supprimer la copie","Modellkopie entfernen"),entry("Close","Cerrar","Fermer","Schließen"),entry("Cancel","Cancelar","Annuler","Abbrechen"),entry("Save","Guardar","Enregistrer","Speichern"),entry("Reset defaults","Restablecer valores","Valeurs par défaut","Standardwerte"),entry("Theme","Tema","Thème","Design"),entry("Navigation language","Idioma de navegación","Langue de navigation","Navigationssprache"),entry("Table number locale","Formato numérico de tablas","Format numérique des tableaux","Zahlenformat der Tabellen"),entry("Decimal places","Decimales","Décimales","Dezimalstellen"),entry("Font size","Tamaño de letra","Taille du texte","Schriftgröße"),entry("Undo states","Estados de deshacer","États d'annulation","Rückgängig-Schritte"),entry("Undo budget (MiB)","Memoria de deshacer (MiB)","Mémoire d'annulation (Mio)","Speicher für Rückgängig (MiB)"),entry("Dataset cell limit","Límite de celdas","Limite de cellules","Zellengrenze"),entry("Report section","Sección del informe","Section du rapport","Berichtsabschnitt"),entry("Details and assumptions","Detalles y supuestos","Détails et hypothèses","Details und Annahmen")
    );
    private static Map.Entry<String,String[]> entry(String key,String es,String fr,String de){return Map.entry(key,new String[]{es,fr,de});}
}
